describe('JavaScript Confirm Dialog', () => {
  beforeEach(() => {
    cy.visit('https://the-internet.herokuapp.com/javascript_alerts');
  });

  it('should record user choice when confirming a JavaScript dialog', () => {
    cy.get('[data-testid="Click for JS Confirm"]').click();
    cy.get('[data-testid="result"]').should('be.visible');
    cy.get('[data-testid="result"]').should('contain', 'You clicked: Ok');
  });

  it('should record user choice when dismissing a JavaScript dialog', () => {
    cy.get('[data-testid="Click for JS Confirm"]').click();
    cy.get('[data-testid="result"]').should('be.visible');
    cy.get('[data-testid="result"]').should('contain', 'You clicked: Cancel');
  });
});
